const $=id=>document.getElementById(id), KEY='digital-services-v1';
let records=[],editing=null,view=[];
const stages=['','검토 중','협의 중','개발 중','테스트 중','개통 완료'];
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date());
const validDate=date=>typeof date==='string'&&(date===''||(/^\d{4}-\d{2}-\d{2}$/.test(date)&&date>='1900-01-01'&&Number.isFinite(Date.parse(date))&&new Date(date).toISOString().slice(0,10)===date));
const valid=r=>r&&(r.stage===undefined||stages.includes(r.stage))&&['id','name','openOrg','launchOrg'].every(k=>typeof r[k]==='string'&&r[k].trim())&&['name','openOrg','launchOrg'].every(k=>r[k].length<=200)&&validDate(r.date);
let timer;function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',3500)}
try{const v=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(v)||!v.every(valid))throw Error();records=v;
// Apply the requested bulk stage update once to existing records.
const stageUpdateKey=KEY+'-completed-stage-20261028';
if(localStorage.getItem(stageUpdateKey)!=='done'){
  const updated=records.map(r=>r.date&&r.date<='2026-10-28'?{...r,stage:'개통 완료'}:r);
  try{
    localStorage.setItem(KEY,JSON.stringify(updated));
    records=updated;
    localStorage.setItem(stageUpdateKey,'done');
  }catch{setTimeout(()=>toast('추진단계 일괄 변경을 저장하지 못했습니다. 저장 공간을 확인한 뒤 새로고침해 주세요.'),100)}
}
}catch{setTimeout(()=>toast('저장 자료를 읽지 못했습니다. 백업 파일을 확인해 주세요.'),100)}
function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));records=next;render();return true}catch{toast('저장하지 못했습니다. 브라우저 저장 공간과 설정을 확인하세요.');return false}}
function cell(tr,s){const td=document.createElement('td');td.textContent=s;tr.append(td);return td}
function render(){const t=today(),q=$('query').value.trim().toLocaleLowerCase(),status=$('status').value,from=$('from').value,to=$('to').value;view=records.filter(r=>(!q||[r.name,r.openOrg,r.launchOrg].some(s=>s.toLocaleLowerCase().includes(q)))&&($('stageFilter').value==='all'||(r.stage||'')===$('stageFilter').value)&&(!from||r.date>=from)&&(!to||(r.date&&r.date<=to))&&(!status||(status==='undated'?!r.date:status==='planned'?r.date>t:!!r.date&&r.date<=t)));view.sort((a,b)=>$('sort').value==='name'?a.name.localeCompare(b.name,'ko'):!a.date&&!b.date?0:!a.date?1:!b.date?-1:$('sort').value==='asc'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));$('total').textContent=records.length;$('done').textContent=records.filter(r=>r.date&&r.date<=t).length;$('planned').textContent=records.filter(r=>r.date>t).length;$('orgs').textContent=new Set(records.map(r=>r.openOrg)).size;$('count').textContent=view.length+'건';$('result').textContent=`전체 ${records.length}건 · 조회 ${view.length}건`;$('rows').replaceChildren();for(const r of view){const tr=document.createElement('tr');['name','openOrg','launchOrg'].forEach(k=>cell(tr,r[k]));const badge=document.createElement('span');badge.className='badge'+(!r.date||r.date>t?' future':'');badge.textContent=!r.date?'일자 미정':r.date>t?'개통 예정':'개통 완료';cell(tr,'').append(badge);cell(tr,r.date||'미정');cell(tr,r.stage||'미지정');const actions=cell(tr,'');for(const [label,fn]of [['수정',()=>openForm(r)],['삭제',()=>{if(confirm(`「${r.name}」 서비스를 삭제하시겠습니까?`)&&save(records.filter(x=>x.id!==r.id)))toast('서비스를 삭제했습니다.')}]] ){const b=document.createElement('button');b.className='rowbtn'+(label==='삭제'?' danger':'');b.textContent=label;b.setAttribute('aria-label',r.name+' '+label);b.onclick=fn;actions.append(b,' ')}$('rows').append(tr)}$('empty').style.display=view.length?'none':'block';$('empty').replaceChildren();if(!view.length){const strong=document.createElement('strong');strong.textContent=records.length?'검색 결과가 없습니다':'등록된 서비스가 없습니다';$('empty').append(strong,records.length?'검색어나 필터를 변경해 주세요.':'‘서비스 등록’을 눌러 첫 개통 정보를 입력하세요.')}}
function openForm(r){editing=r?.id||null;$('form').reset();$('formTitle').textContent=r?'서비스 수정':'서비스 등록';for(const k of ['name','openOrg','launchOrg','date','stage'])$(k).value=r?.[k]||'';$('modal').showModal()}
$('add').onclick=()=>openForm();$('cancel').onclick=()=>$('modal').close();$('form').onsubmit=e=>{e.preventDefault();const r={id:editing||crypto.randomUUID()};for(const k of ['name','openOrg','launchOrg','date','stage'])r[k]=$(k).value.trim();if(!valid(r)){toast('필수 항목과 입력한 날짜가 올바른지 확인해 주세요.');return}if(records.some(x=>x.id!==r.id&&['name','openOrg','launchOrg','date'].every(k=>x[k]===r[k]))){toast('동일한 서비스 정보가 이미 등록되어 있습니다.');return}if(save(editing?records.map(x=>x.id===editing?r:x):[...records,r])){$('modal').close();toast(editing?'수정 내용을 저장했습니다.':'서비스를 등록했습니다.')}};
for(const id of ['query','status','from','to','sort','stageFilter'])$(id).addEventListener('input',render);$('reset').onclick=()=>{for(const id of ['query','status','from','to'])$(id).value='';$('stageFilter').value='all';render()};
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('csv').onclick=()=>{const esc=s=>'"'+(/^[=+@\-\t\r]/.test(s)?"'"+s:s).replaceAll('"','""')+'"';download('\uFEFF'+[['개통서비스명','개방기관','개통기업','개통일자','개방업무 추진단계'],...view.map(r=>[r.name,r.openOrg,r.launchOrg,r.date,r.stage||'미지정'])].map(row=>row.map(esc).join(',')).join('\r\n'),'text/csv;charset=utf-8',`개통서비스_${today()}.csv`)};
$('backup').onclick=()=>download(JSON.stringify({version:1,records},null,2),'application/json',`개통서비스_백업_${today()}.json`);$('restore').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10000000)throw Error();const v=JSON.parse(await f.text());if(v.version!==1||!Array.isArray(v.records)||!v.records.every(valid)||new Set(v.records.map(x=>x.id)).size!==v.records.length)throw Error();if(confirm(`현재 자료 ${records.length}건을 백업 자료 ${v.records.length}건으로 교체하시겠습니까?`)&&save(v.records))toast('백업 자료를 복원했습니다.')}catch{toast('올바른 백업 파일이 아닙니다. 파일 형식을 확인하세요.')}e.target.value=''};render();
